def solve(record):
    # Read the raw entrant data.
    x = record.get('record_1', [])

    # For each entrant, the board announces only their winning (best) score.
    best = {}
    first_seen = {}
    for idx, row in enumerate(x):
        name = row[0]
        # Missing/None points are ignored (board announces only winning scores).
        points = row[1] if len(row) > 1 and row[1] is not None else None
        if name not in first_seen:
            first_seen[name] = idx
            best[name] = points
        else:
            if points is not None:
                if best[name] is None or points > best[name]:
                    best[name] = points

    # Entrants without any winning score cannot be ranked; the receiving
    # system accepts empty lists, so drop them if the board announced nothing.
    ranked = [n for n in best if best[n] is not None]

    # Sort by descending points; ties keep registration order.
    ranked.sort(key=lambda n: (-best[n], first_seen[n]))

    # Return just the names.
    return ranked
