from collections import deque, defaultdict


def solve(record):
    def bfs(adjacency, start, goal):
        if start == goal:
            return 0
        dist = {start: 0}
        q = deque([start])
        while q:
            cur = q.popleft()
            for nxt in adjacency[cur]:
                if nxt not in dist:
                    dist[nxt] = dist[cur] + 1
                    if nxt == goal:
                        return dist[nxt]
                    q.append(nxt)
        return -1

    x = record['record_2']
    edges, source, target = x[0], x[1], x[2]

    adj = defaultdict(list)
    for u, v in edges:
        if u == v:
            continue
        adj[u].append(v)
        adj[v].append(u)

    if source != target:
        return bfs(adj, source, target)

    # Self-transfer: need the shortest positive-length round trip
    # (shortest cycle passing through `source`).
    best = -1
    for n in list(adj[source]):
        # Temporarily remove one instance of the direct edge (source, n)
        adj[source].remove(n)
        adj[n].remove(source)
        d = bfs(adj, source, n)
        # Restore the edge instance
        adj[source].append(n)
        adj[n].append(source)
        if d != -1:
            cycle_len = d + 1
            if best == -1 or cycle_len < best:
                best = cycle_len
    return best
```

