def solve(record):
    from collections import deque

    x = record['record_1']
    edges, source, target = x[0], x[1], x[2]

    if source == target:
        return 0

    adj = {}
    for a, b in edges:
        adj.setdefault(a, []).append(b)

    if source not in adj:
        return None

    visited = {source}
    queue = deque([(source, 0)])

    while queue:
        node, dist = queue.popleft()
        for nxt in adj.get(node, []):
            if nxt == target:
                return dist + 1
            if nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, dist + 1))

    return None
